SELECT quantity_bucket, stddev_quantity, last_last_restock FROM (SELECT CASE WHEN quantity >= 256 THEN 'high' WHEN quantity >= 73 THEN 'mid' ELSE 'low' END quantity_bucket, ROUND(STDDEV(quantity), 2) stddev_quantity, MAX(last_restock) last_last_restock FROM inventory WHERE product_id IN (1, 2, 8) GROUP BY CASE WHEN quantity >= 256 THEN 'high' WHEN quantity >= 73 THEN 'mid' ELSE 'low' END) sub WHERE stddev_quantity > 58 ORDER BY quantity_bucket ASC;
